    fusedValid ? _post_io_rawOut_isZero : a_isZero | b_isZero;
  assign io_result_bits_value_sign = fusedValid ? _post_io_rawOut_sign : a_sign ^ b_sign;
  assign io_result_bits_value_sExp =
    fusedValid ? _post_io_rawOut_sExp : a_sExp + b_sExp - 10'h100;
  assign io_result_bits_value_sig =
    fusedValid ? _post_io_rawOut_sig : {product[47:22], |(product[21:0])};
  assign io_result_bits_invalid =
    fusedValid
      ? _post_io_invalidExc
      : a_isNaN & ~(a_sig[22]) | b_isNaN & ~(b_sig[22]) | a_isInf & b_isZero | a_isZero
        & b_isInf;
endmodule

